function maximumPossibleSize(nums) {
  // Any final array comes from cutting nums into consecutive blocks and keeping each block's maximum.
  // Try every set of cuts and keep the most blocks whose maxima never decrease.
  const n = nums.length;
  let best = 0;
  for (let mask = 0; mask < 2 ** (n - 1); mask++) {
    const maxima = [];
    let current = nums[0];
    for (let i = 1; i < n; i++) {
      if (Math.floor(mask / 2 ** (i - 1)) % 2 === 1) {
        maxima.push(current);
        current = nums[i];
      } else {
        current = Math.max(current, nums[i]);
      }
    }
    maxima.push(current);
    const ordered = maxima.every((m, j) => j === 0 || maxima[j - 1] <= m);
    if (ordered && maxima.length > best) best = maxima.length;
  }
  return best;
}

