function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const shape = Math.floor(rand() * 3);
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (shape === 0) {
      // Random values over the whole range: few running maxima.
      nums.push(1 + Math.floor(rand() * 200000));
    } else if (shape === 1) {
      // A rising trend with noise: many running maxima, some dips.
      const step = size === 'large' ? 90 : 3;
      nums.push(Math.min(200000, 1 + Math.floor(i * step + rand() * step * 4)));
    } else {
      // Few distinct values: many ties with the running maximum.
      nums.push(1 + Math.floor(rand() * (size === 'large' ? 3 : 4)));
    }
  }
  return [nums];
}
